def transform(g):
    g=[r[:] for r in g]
    H,W=len(g),len(g[0])
    # find divider: row all same nonzero, or col all same nonzero
    import itertools
    div=None
    for j in range(W):
        col={g[i][j] for i in range(H)}
        if len(col)==1 and 0 not in col:
            div=('col',j); break
    if div is None:
        for i in range(H):
            row={g[i][j] for j in range(W)}
            if len(row)==1 and 0 not in row:
                div=('row',i); break
    if div[0]=='col':
        j=div[1]; A=[r[:j] for r in g]; B=[r[j+1:] for r in g]
    else:
        i=div[1]; A=g[:i]; B=g[i+1:]
    return [[2 if a!=0 and b!=0 else 0 for a,b in zip(ra,rb)] for ra,rb in zip(A,B)]
